arguments.command:
command -v bashlex >/dev/null 2>&1 && echo "have-bashlex" || echo "no-bashlex-cli"; command -v shfmt >/dev/null 2>&1 && echo "have-shfmt" || echo "no-shfmt"; command -v shellcheck >/dev/null 2>&1 && echo "have-shellcheck" || echo "no-shellcheck"; echo "---verify sample parses---"; cat <<'EOF'
cd /home/bhd/Documents/Projects/bhd/beet-orches && echo "=== find manual-line route ==="; timeout 15 grep -rnE "manual.*line|line.*item|POST.*line|/lines" components/mod-contractor-payment/backend/src/routes/invoices.ts 2>/dev/null | grep -iE "line|manual" | head -15
EOF
echo "---naive parser trace (per design)---"
node -e '
const c = `cd /home/bhd/Documents/Projects/bhd/beet-orches && echo "=== find manual-line route ==="; timeout 15 grep -rnE "manual.*line|line.*item|POST.*line|/lines" components/mod-contractor-payment/backend/src/routes/invoices.ts 2>/dev/null | grep -iE "line|manual" | head -15`;
let cmd = c.replace(/^cd\s+\S+\s+(&&|;)\s*/, "");
cmd = cmd.replace(/^(\w+=\S+\s+)+/, "");
cmd = cmd.replace(/^(sudo\s+|timeout\s+\S+\s+)+/, "");
const parts = cmd.split("|").map(p=>p.trim());
console.log("AFTER STRIP:", JSON.stringify(cmd.slice(0,80)));
console.log("PIPE PARTS:", parts.length);
parts.forEach((p,i)=>console.log("  ["+i+"]", JSON.stringify(p.slice(0,60))));
const tokens = parts[0].split(/\s+/);
console.log("PROGRAM:", tokens[0]);
console.log("FLAGS:", tokens.filter(a=>a.startsWith("-")));
'

